// `root_element` is the block's shadow root, supplied by frappe.
const links = Array.from(root_element.querySelectorAll('.ws-link'));

function setIcons() {
	// Same lookup the desk sidebar and app switcher use, so these pills carry
	// the exact same artwork (and respect the site's Solid/Subtle icon style).
	const style = frappe.boot.desktop_icon_style || 'Subtle';
	links.forEach((link) => {
		const label = link.querySelector('.ws-label').textContent.trim();
		const iconEl = link.querySelector('.ws-icon');
		const iconUrl = frappe.utils.get_desktop_icon(label, style);
		iconEl.innerHTML = iconUrl
			? `<img src="${iconUrl}" alt="" />`
			: frappe.utils.desktop_icon(label, 'gray', 'sm');
	});
}

function currentSlug() {
	// v16 serves the desk at /desk/<workspace>; /app/<workspace> still redirects
	// there, so accept either base.
	const parts = window.location.pathname.split('/').filter(Boolean);
	const isDesk = parts[0] === 'desk' || parts[0] === 'app';
	return isDesk && parts[1] ? parts[1].toLowerCase() : '';
}

function markCurrent() {
	const slug = currentSlug();
	links.forEach((link) => {
		const isCurrent = link.dataset.slug === slug;
		link.classList.toggle('is-current', isCurrent);
		if (isCurrent) {
			link.setAttribute('aria-current', 'page');
		} else {
			link.removeAttribute('aria-current');
		}
	});
}

links.forEach((link) => {
	link.addEventListener('click', (event) => {
		// Shadow DOM retargets clicks, so frappe's global anchor handler never
		// sees this <a>. Route by hand, otherwise every click is a full reload.
		event.preventDefault();
		if (link.classList.contains('is-current')) return;
		// Deferred: routing synchronously would rebuild the workspace, and this
		// block, while the click that triggered it is still being dispatched.
		setTimeout(() => frappe.set_route(link.dataset.slug), 0);
	});
});

setIcons();
markCurrent();

// Keep the highlight right if the desk swaps workspaces without rebuilding
// this block. Bails out once the block's host element is detached.
frappe.router.on('change', () => {
	if (root_element.host && root_element.host.isConnected) markCurrent();
});

style:
/* Rendered inside a shadow root with desk.bundle.css linked. Frappe's CSS
   variables inherit across the shadow boundary, so they resolve here, and these
   class names cannot leak out.

   Styled after the pill buttons on the churchit marketing site: fully rounded,
   tinted, lifting a little on hover, with the site's indigo/violet/pink
   gradient marking the workspace you are on. */
.ws-header {
	display: flex;
	flex-wrap: wrap;
	align-items: center;
	gap: 6px;
	padding-bottom: 10px;
	margin-bottom: 4px;
	/* The site's gradient as a 1px rule, fading out on both ends, instead of a
	   flat border. Drawn as a background so it can be a gradient at all. */
	background-image: linear-gradient(
		90deg,
		transparent 0%,
		rgba(99, 102, 241, 0.55) 12%,
		rgba(139, 92, 246, 0.45) 50%,
		rgba(236, 72, 153, 0.35) 88%,
		transparent 100%
	);
	background-repeat: no-repeat;
	background-position: left bottom;
	background-size: 100% 1px;
}

/* One tint per module, matching that module's own icon color (see
   public/icons/desktop_icons) rather than frappe's generic palette, so the
   hover halo reads as "the icon's color, softened" instead of an unrelated
   tint. Low alpha keeps default text legible over it in both themes without
   this block having to detect the theme itself — it cannot, since :root
   matches nothing inside a shadow root and :host-context() is not supported
   everywhere. */
.ws-link[data-slug="summary"] { --ws-bg: rgba(34, 197, 94, 0.18); }
.ws-link[data-slug="communications"] { --ws-bg: rgba(59, 130, 246, 0.18); }
.ws-link[data-slug="finances"] { --ws-bg: rgba(16, 185, 129, 0.18); }
.ws-link[data-slug="foundations"] { --ws-bg: rgba(168, 85, 247, 0.18); }
.ws-link[data-slug="ministries"] { --ws-bg: rgba(236, 72, 153, 0.18); }
.ws-link[data-slug="missions"] { --ws-bg: rgba(14, 165, 233, 0.18); }
.ws-link[data-slug="operations"] { --ws-bg: rgba(249, 115, 22, 0.18); }
.ws-link[data-slug="people"] { --ws-bg: rgba(20, 184, 166, 0.18); }
.ws-link[data-slug="prayers"] { --ws-bg: rgba(139, 92, 246, 0.18); }
.ws-link[data-slug="study"] { --ws-bg: rgba(245, 158, 11, 0.18); }
.ws-link[data-slug="web-site"] { --ws-bg: rgba(6, 182, 212, 0.18); }
.ws-link[data-slug="settings"] { --ws-bg: rgba(100, 116, 139, 0.18); }
.ws-link[data-slug="help"] { --ws-bg: rgba(224, 90, 76, 0.18); }

.ws-link {
	display: inline-flex;
	align-items: center;
	/* Equal on all sides so the collapsed, icon-only pill is a centered circle
	   around the icon rather than a wide oval; it opens into a stadium shape
	   once the label expands. */
	padding: 7px;
	border: 1px solid transparent;
	border-radius: 999px;
	font-size: var(--text-sm);
	font-weight: 500;
	line-height: 1.5;
	white-space: nowrap;
	text-decoration: none;
	/* No tint until hover/focus — at rest only the icon's own artwork shows. */
	background-color: transparent;
	color: var(--text-on-gray);
	transition: background-color 0.15s ease, transform 0.12s ease, box-shadow 0.15s ease,
		filter 0.12s ease;
}

.ws-link:hover,
.ws-link:focus-visible {
	background-color: var(--ws-bg, var(--bg-gray));
	color: var(--text-on-gray);
	text-decoration: none;
	transform: translateY(-1px);
	box-shadow: var(--shadow-sm);
	filter: saturate(1.3);
}

.ws-link:focus-visible {
	outline: 2px solid var(--brand-color);
	outline-offset: 2px;
}

.ws-icon {
	display: inline-flex;
	align-items: center;
	justify-content: center;
	width: 27px;
	height: 27px;
	flex-shrink: 0;
}

.ws-icon img,
.ws-icon svg {
	width: 100%;
	height: 100%;
	display: block;
}

/* Collapsed to the icon by default, matching the desk's icon-only dock. The
   label lives in the same pill rather than a separate tooltip, and slides in
   next to the icon on hover/focus so it never covers neighbouring pills. */
.ws-label {
	display: inline-block;
	max-width: 0;
	margin-left: 0;
	opacity: 0;
	overflow: hidden;
	white-space: nowrap;
	vertical-align: middle;
	transition: max-width 0.2s ease, margin-left 0.2s ease, opacity 0.15s ease;
}

/* The current page can't be hovered (see .is-current below), so its label
   stays expanded for orientation instead of requiring focus to reveal it. */
.ws-link:hover .ws-label,
.ws-link:focus-visible .ws-label,
.ws-link.is-current .ws-label {
	max-width: 12em;
	margin-left: 6px;
	opacity: 1;
}

/* The workspace you are already on: the site's primary-button gradient, shown
   for orientation but not a link. background-origin keeps the gradient aligned
   to the outer edge so the 1px transparent border leaves no colour fringe.

   Same indigo -> violet -> pink ramp as .btn-primary on the site, one step
   darker (the 600s, not the 500s). White on the site's 500 ramp is 3.5:1 at the
   pink end, which is fine for its 1rem buttons but not for 12px desk text; the
   600s keep the look and clear 4.6:1 across every stop. */
.ws-link.is-current {
	background-image: linear-gradient(120deg, #4f46e5 0%, #7c3aed 50%, #db2777 100%);
	background-origin: border-box;
	color: #fff;
	font-weight: 600;
	box-shadow: 0 6px 16px -8px rgba(79, 70, 229, 0.9);
	cursor: default;
	pointer-events: none;
}

@media (prefers-reduced-motion: reduce) {
	.ws-link,
	.ws-label {
		transition: none;
	}

	.ws-link:hover,
	.ws-link:focus-visible {
		transform: none;
	}
}
